// Conformance against the risk engine's own FX vectors.
//
// The dashboard converts for display and the Go engine converts for pricing.
// Two implementations of the same arithmetic will drift; the only question is
// whether anyone notices. These 48 cases are generated BY the engine from the
// same rate table, so this file is what turns "should agree" into "does agree".
//
// The cases were chosen adversarially by the model side, and every one of them
// fails against the obvious JS implementation:
//   - negatives, because Math.round is half-up rather than half-away-from-zero
//   - .x5 boundaries, because toFixed rounds the binary double not the decimal
//   - JPY, because it has no minor unit at all

import { describe, it, expect } from 'vitest'
import vectors from './__fixtures__/fxTestVectors.json'
import { convert, roundHalfAwayFromZero } from './convert'
import { money } from './money'
import { minorUnits, type CurrencyCode } from './currency'
import { rateFor, DEFAULT_RATE_TABLE, type RateTable } from './rates'

interface Vector {
  from: string
  to: string
  amount: number
  rate: number
  converted: number
  converted_rounded: number
  minor_units: number
}

const cases = vectors.cases as Vector[]

describe('FX conformance with the risk engine', () => {
  it('ships a non-trivial number of cases — an empty file must not read as a pass', () => {
    expect(cases.length).toBeGreaterThanOrEqual(48)
  })

  it.each(cases)(
    '$amount $from -> $to = $converted_rounded',
    ({ from, to, amount, rate, converted_rounded, minor_units }) => {
      // The rate this dashboard looks up must be the rate the engine priced with.
      const lookup = rateFor(from as CurrencyCode, to as CurrencyCode)
      expect(lookup).not.toBeNull()
      expect(lookup?.rate).toBeCloseTo(rate, 12)

      // Minor units come from Intl rather than the vector, so this asserts the
      // platform agrees with the engine about what a currency's decimals are.
      expect(minorUnits(to as CurrencyCode)).toBe(minor_units)

      const result = convert(money(amount, from as CurrencyCode), to as CurrencyCode)
      expect(result).not.toBeNull()
      expect(result?.amount).toBe(converted_rounded)
    },
  )
})

// ── Is this suite actually testing anything? ────────────────────────────────
//
// A conformance suite can pass for the wrong reason. On this branch a test
// oracle computed its expected value from `rates.USD` — which is 1 under a
// USD-based table — and so compared a figure against itself and went green on
// nothing. The model side then found the mirror of it: a Go test whose comment
// claimed it caught an inverted rate, when a round trip applies a wrong factor
// and its reciprocal and lands back where it started, so it never could.
//
// The defence against both is mutation: break the thing under test on purpose
// and count how many cases notice. A case that survives a deliberately wrong
// rate is not testing conversion, whatever its name says.
describe('the conformance suite is not vacuous', () => {
  function mutated(kind: 'identity' | 'inverted'): RateTable {
    const pairs: Record<string, Record<string, number>> = {}
    for (const [from, row] of Object.entries(DEFAULT_RATE_TABLE.pairs)) {
      pairs[from] = {}
      for (const [to, rate] of Object.entries(row)) {
        pairs[from][to] = kind === 'identity' ? 1 : 1 / rate
      }
    }
    return { ...DEFAULT_RATE_TABLE, pairs }
  }

  /** Cases that still produce the expected figure despite a broken rate table. */
  function survivors(kind: 'identity' | 'inverted'): Vector[] {
    return cases.filter((c) => {
      const got = convert(money(c.amount, c.from as CurrencyCode), c.to as CurrencyCode, mutated(kind))
      return got?.amount === c.converted_rounded
    })
  }

  // A case can legitimately survive for exactly two reasons, and both are
  // properties of the case rather than weaknesses in it:
  //   - from === to, where the rate genuinely is 1
  //   - amount === 0, where zero times any rate is zero
  const explainable = (c: Vector) => c.from === c.to || c.amount === 0

  it.each(['identity', 'inverted'] as const)(
    'every case that survives a %s rate mutation is explainably immune',
    (kind) => {
      const unexplained = survivors(kind).filter((c) => !explainable(c))
      expect(unexplained.map((c) => `${c.amount} ${c.from}->${c.to}`)).toEqual([])
    },
  )

  it('kills the large majority of cases under a wrong rate', () => {
    // 40 of the 48 are cross-currency; 5 of those are zero-amount. So 35 must
    // die. Asserting a floor rather than the exact number leaves room for the
    // engine to add cases without this failing spuriously.
    for (const kind of ['identity', 'inverted'] as const) {
      const killed = cases.length - survivors(kind).length
      expect(killed).toBeGreaterThanOrEqual(35)
    }
  })

  it('detects an inverted rate specifically — the reciprocal trap', () => {
    // The failure this branch nearly shipped: base USD read as though it were
    // base GBP, multiplying by 0.79 where 1.2658 was wanted. A round-trip test
    // cannot catch this; a fixed expected value can.
    const inverted = convert(money(1000, 'GBP'), 'USD', mutated('inverted'))
    const correct = convert(money(1000, 'GBP'), 'USD')
    expect(inverted?.amount).not.toBe(correct?.amount)
  })
})

describe('the rounding rule the vectors are testing', () => {
  it('rounds half AWAY FROM ZERO, symmetrically about zero', () => {
    expect(roundHalfAwayFromZero(2.675, 2)).toBe(2.68)
    expect(roundHalfAwayFromZero(-2.675, 2)).toBe(-2.68)
    // Math.round would give -2.67 for the negative: half-up, not symmetric.
    expect(Math.round(-267.5) / 100).toBe(-2.67)
  })

  it('rounds the decimal the reader typed, not the binary double', () => {
    expect(roundHalfAwayFromZero(2.675, 2)).toBe(2.68)
    // The trap, pinned so nobody "simplifies" the implementation back into it.
    expect((2.675).toFixed(2)).toBe('2.67')
  })

  it('rounds to whole units for a currency with no minor unit', () => {
    expect(roundHalfAwayFromZero(196202.5316456, 0)).toBe(196203)
    expect(roundHalfAwayFromZero(-524.8417721519, 0)).toBe(-525)
  })

  it('leaves zero alone and does not produce negative zero', () => {
    expect(Object.is(roundHalfAwayFromZero(0, 2), 0)).toBe(true)
  })

  it('returns NaN for a non-finite input rather than inventing a figure', () => {
    expect(roundHalfAwayFromZero(Number.NaN, 2)).toBeNaN()
    expect(roundHalfAwayFromZero(Number.POSITIVE_INFINITY, 2)).toBeNaN()
  })
})

describe('the direction of the rate table', () => {
  it('takes GBP up into USD, not down — the reciprocal trap', () => {
    // rates.GBP is 0.79 (units per USD). Using it directly for GBP->USD would
    // turn 1000 into 790 instead of 1266: a factor of 1.6, plausible and
    // silent. pairs[GBP][USD] is the 1.2658 that is actually wanted.
    const converted = convert(money(1000, 'GBP'), 'USD')
    expect(converted?.amount).toBeGreaterThan(1000)
    expect(converted?.rate).toBeCloseTo(1.2658227848101264, 12)
  })

  it('takes USD down into GBP', () => {
    const converted = convert(money(1000, 'USD'), 'GBP')
    expect(converted?.amount).toBeLessThan(1000)
    expect(converted?.amount).toBe(790)
  })

  it('is exactly 1 for an identity conversion, so existing figures cannot move', () => {
    // The regression anchor: every GBP figure already in the repo must render
    // byte-identically for a user who has chosen GBP.
    expect(rateFor('GBP', 'GBP')?.rate).toBe(1)
    expect(convert(money(13346.97276384128, 'GBP'), 'GBP')?.amount).toBe(13346.97)
  })

  it('round-trips within a minor unit', () => {
    const there = convert(money(1000, 'GBP'), 'USD')
    const back = convert(money(there!.amount, 'USD'), 'GBP')
    expect(Math.abs((back?.amount ?? 0) - 1000)).toBeLessThanOrEqual(0.01)
  })
})
